// #597ccf (bda08b8d4fb6c3dcfb597ccf) — «קליטת בקשה» Super Admin: дата «сегодня» по Израилю принимается после полуночи,
// «завтра» по Израилю отклоняется. Кейсы DREQ-006…DREQ-009.
// Часы браузера фиксируются на 00:30 по Израилю (зимой 22:30 UTC предыдущих суток) через page.clock — «ночь» воспроизводится
// в любое время суток. Часы подменяют ТОЛЬКО клиент; серверную часть в «окне» (UTC-дата ≠ IL-дата) проверяет лишь реальная
// ночь 00:00–02:00 IST (проверено вручную 18.11 00:30 IST) — здесь сервер получает дату = реальное «сегодня» по IL.
// Данные: создаётся ровно одна заявка (DREQ-006, @data, note QA-597ccf-<дата>); удаления заявок в продукте нет —
// она остаётся в списке «התקבלה». Остальные кейсы заявок не создают (блок/подмена RPC записи или 400 на пустых id).
import * as path from 'path';
import { test, expect, Page } from '@playwright/test';

test.use({
  storageState: path.resolve(__dirname, '../../../auth/admin.json'),
  locale: 'he-IL',
  timezoneId: 'Asia/Jerusalem',
});

const HASH = '#597ccf';
const URL_PATH = '/admin/data-requests';
const CREATE_RPC = /\/rpc\/admin_create_data_request/;
const FUTURE_MSG = 'יש להזין את תאריך הקבלה (לא בעתיד)';

const IL = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Jerusalem', year: 'numeric', month: '2-digit', day: '2-digit' });
const ilDate = (d: Date) => IL.format(d); // YYYY-MM-DD по Израилю
const addDays = (ymd: string, n: number) => {
  const d = new Date(`${ymd}T00:00:00Z`);
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};
/** Момент «00:30 по Израилю» заданного IL-дня (зимой UTC+2, летом UTC+3). */
function ilHalfPastMidnight(ymd: string): Date {
  const [y, m, d] = ymd.split('-').map(Number);
  for (const off of [2, 3]) {
    const t = new Date(Date.UTC(y, m - 1, d, 0, 30) - off * 3_600_000);
    if (ilDate(t) === ymd) return t;
  }
  throw new Error(`нет момента 00:30 IL для ${ymd}`);
}

const TODAY_IL = ilDate(new Date());
const NIGHT = ilHalfPastMidnight(TODAY_IL); // 00:30 IL реального «сегодня»
const YESTERDAY_IL = addDays(TODAY_IL, -1);
const TOMORROW_IL = addDays(TODAY_IL, 1);
const NOTE = `QA-597ccf-${TODAY_IL}`;

async function openIntakeAtNight(page: Page) {
  await page.clock.install({ time: NIGHT });
  await page.goto(URL_PATH);
  await page.getByRole('button', { name: 'קליטת בקשה' }).first().click();
  const panel = page.getByTestId('data-request-intake');
  await expect(panel.getByText('סוג הבקשה').first()).toBeVisible();
  return panel;
}

/** Заполняет всё, кроме даты: любой тип, первый бизнес и первый кандидат из списка. */
async function fillExceptDate(panel: ReturnType<Page['getByTestId']>) {
  await panel.getByLabel('סוג הבקשה').selectOption({ index: 1 });
  await panel.getByLabel('בית עסק').selectOption({ index: 1 });
  const candidate = panel.getByLabel('מועמד/ת');
  await expect(candidate.locator('option')).not.toHaveCount(1); // кандидаты бизнеса загрузились
  await candidate.selectOption({ index: 1 });
  await panel.getByLabel('תיאור הבקשה').fill(NOTE);
}

test.describe(`Админка — «קליטת בקשה»: дата по Израилю (${HASH})`, () => {
  test(`DREQ-006 в 00:30 IL дата по умолчанию = сегодня IL, отправка принимается (RPC 200, заявка в списке) @desktop @data ${HASH}`, async ({ page }) => {
    const panel = await openIntakeAtNight(page);
    // Источник: AC1 / «מה רצוי» — «сегодня» по Израилю = значение по умолчанию и принимается.
    await expect(panel.getByLabel('תאריך קבלה')).toHaveValue(TODAY_IL);
    await fillExceptDate(panel);

    const before = await page.getByTestId('data-request-row').count();
    const resp = page.waitForResponse((r) => CREATE_RPC.test(r.url()) && r.request().method() === 'POST');
    await panel.getByRole('button', { name: 'קליטת הבקשה' }).click();
    expect((await resp).status(), 'admin_create_data_request с датой сегодняшнего дня IL').toBe(200);

    await expect(panel.getByText(FUTURE_MSG)).toHaveCount(0);
    await expect(panel).toBeHidden(); // панель закрывается после приёма
    await expect(page.getByTestId('data-request-row')).toHaveCount(before + 1);
  });

  test(`DREQ-007 в 00:30 IL «завтра» по IL отклоняется: «לא בעתיד», запрос не уходит @desktop ${HASH}`, async ({ page }) => {
    const sent: string[] = [];
    page.on('request', (r) => CREATE_RPC.test(r.url()) && sent.push(r.url()));
    const panel = await openIntakeAtNight(page);
    await fillExceptDate(panel);
    await panel.getByLabel('תאריך קבלה').fill(TOMORROW_IL);

    await panel.getByRole('button', { name: 'קליטת הבקשה' }).click();
    // Источник: AC2 — завтрашняя дата по Израилю отклоняется, как раньше.
    await expect(panel.getByText(FUTURE_MSG)).toBeVisible();
    await expect(panel).toBeVisible();
    expect(sent, 'запросов admin_create_data_request быть не должно').toEqual([]);
  });

  test(`DREQ-008 в 00:30 IL «вчера» принимается формой (подмена RPC записи, данные не создаются) @desktop ${HASH}`, async ({ page }) => {
    const bodies: string[] = [];
    await page.route(CREATE_RPC, (route) => {
      bodies.push(route.request().postData() ?? '');
      return route.fulfill({ status: 200, contentType: 'application/json', body: '{}' });
    });
    const panel = await openIntakeAtNight(page);
    await fillExceptDate(panel);
    await panel.getByLabel('תאריך קבלה').fill(YESTERDAY_IL);

    await panel.getByRole('button', { name: 'קליטת הבקשה' }).click();
    // Источник: AC1 (прошлое принимается; ранее ✅ 18.11 «вчера → 200») — клиент не блокирует и шлёт ровно эту дату.
    await expect.poll(() => bodies.length).toBe(1);
    expect(JSON.parse(bodies[0]).p_received_at).toBe(YESTERDAY_IL);
    await expect(panel.getByText(FUTURE_MSG)).toHaveCount(0);
  });

  test(`DREQ-009 API: admin_create_data_request с «завтра» IL → 400 validation_failed: received_at @desktop @prod-safe ${HASH}`, async ({ page }) => {
    // Берём адрес и заголовки у собственного запроса приложения (сессия admin), ключи в тест не записаны.
    const listReq = page.waitForRequest((r) => /\/rpc\/admin_list_data_requests/.test(r.url()));
    await page.goto(URL_PATH);
    const req = await listReq;
    const headers = await req.allHeaders();
    const url = req.url().replace('admin_list_data_requests', 'admin_create_data_request');

    // Пустые id/тип: даже если сервер проверит другие поля — запись невозможна; нас интересует поле received_at.
    const res = await page.request.post(url, {
      headers: { apikey: headers['apikey'], authorization: headers['authorization'], 'content-type': 'application/json' },
      data: {
        p_business_id: null,
        p_candidate_id: null,
        p_request_type: null,
        p_received_at: TOMORROW_IL,
        p_note: NOTE,
        p_requested_by: 'candidate',
        p_due_on: null,
        p_assigned_to: null,
      },
    });
    // Источник: AC2 / комментарий программиста 19.10 — «завтра» IL → validation_failed: received_at.
    expect(res.status()).toBe(400);
    const body = await res.text();
    expect(body).toContain('validation_failed');
    expect(body).toContain('received_at');
  });
});
